// window/quote.js - the only module that knows the legacy shape
import { deprecate } from 'node:util';
export function fromLegacy(dto) {              // old wire -> canonical
  return { sku: dto.SKU, priceCents: Math.round(Number(dto.unit_price) * 100),
           currency: dto.ccy || 'EUR' };        // the default is part of the contract
}
export function toLegacy(q) {                  // canonical -> old wire
  return { SKU: q.sku, unit_price: (q.priceCents / 100).toFixed(2), ccy: q.currency };
}
export const legacyQuote = deprecate(fromLegacy, 'legacy window: only for client X');
